const onTabActivated = (activeInfo) => {
  updateBadgeForTab(ctx, activeInfo.tabId);
  ctx.activeTabIdForPanel = activeInfo.tabId; // synchronous — events now match
  void getTab(activeInfo.tabId).then((tab) => {
    // async revert ONLY if it was an internal chrome-extension/edge tab
    if (tab.url?.startsWith('chrome-extension://') || tab.url?.startsWith('edge://')) {
      ctx.activeTabIdForPanel = undefined;
    }
  });
};

// re-sync on tab load complete for the active tab, pulling cached cues as fallback
chrome.tabs.onUpdated.addListener((tabId, info) => {
  if (info.status === 'complete' && tabId === activeTabId) {
    sendRuntimeMessage({ type: 'REQUEST_SUBTITLE_CUES', tabId });
  }
});
